const OPERATIONS_VIEW_FACTORS: Record<DeliveryView, { count: number; pctDelta: number; returnsPctDelta: number }> = {
  last24h: { count: 0.08, pctDelta: 0.3, returnsPctDelta: -0.4 },
  wtd: { count: 0.34, pctDelta: 0.1, returnsPctDelta: -0.1 },
  mtd: { count: 1, pctDelta: 0, returnsPctDelta: 0 },
  qtd: { count: 2.85, pctDelta: -0.2, returnsPctDelta: 0.2 },
};

function parseMetricNumber(value: string) {
  return Number(value.replace(/,/g, "").replace("%", ""));
}

function scaleMetric(value: string, factor: number, minimum = 0) {
  const scaled = Math.max(minimum, Math.round(parseMetricNumber(value) * factor));
  return formatNumber(scaled);
}

function adjustMetricPercent(value: string, delta: number) {
  return `${adjustPct(parseMetricNumber(value), delta).toFixed(1)}%`;
}

function getOperationsMetrics(client: ClientKey, view: DeliveryView) {
  const base = OPERATIONS_WIDGETS_BY_CLIENT[client];
  const factor = OPERATIONS_VIEW_FACTORS[view];

  return {
    ...base,
    putaway: adjustMetricPercent(base.putaway, factor.pctDelta),
    asnComplianceRate: adjustMetricPercent(base.asnComplianceRate, factor.pctDelta),
    asnsExpected: scaleMetric(base.asnsExpected, factor.count, view === "last24h" ? 1 : 0),
    unitsInPipeline: scaleMetric(base.unitsInPipeline, factor.count, view === "last24h" ? 1 : 0),
    receiveAccuracy: adjustMetricPercent(base.receiveAccuracy, factor.pctDelta),
    discrepancyCount: scaleMetric(base.discrepancyCount, factor.count, 0),
    ordersReceived: scaleMetric(base.ordersReceived, factor.count, view === "last24h" ? 1 : 0),
    despatchedWithinCutoff: scaleMetric(base.despatchedWithinCutoff, factor.count, view === "last24h" ? 1 : 0),
    totalDespatched: scaleMetric(base.totalDespatched, factor.count, view === "last24h" ? 1 : 0),
    shippedAccepted: scaleMetric(base.shippedAccepted, factor.count, view === "last24h" ? 1 : 0),
    inTransit: scaleMetric(base.inTransit, factor.count, view === "last24h" ? 1 : 0),
    outForDelivery: scaleMetric(base.outForDelivery, factor.count, view === "last24h" ? 1 : 0),
    delivered: scaleMetric(base.delivered, factor.count, view === "last24h" ? 1 : 0),
    undeliveredReturnedToSender: scaleMetric(base.undeliveredReturnedToSender, factor.count, 0),
    parcelsReturned: scaleMetric(base.parcelsReturned, factor.count, 0),
    returns: scaleMetric(base.returns, factor.count, 0),
    returnsVsDespatched: adjustMetricPercent(base.returnsVsDespatched, factor.returnsPctDelta),
  };
}


