function getInventoryWidgets(client: ClientKey, range: InventoryWidgetRange) {
  const base = INVENTORY_WIDGETS_BASE[range];
  const config = CLIENT_CONFIG[client];
  return {
    outOfStock: scaleInt(base.outOfStock, config.mult),
    lowStock: scaleInt(base.lowStock, config.mult),
    wellStocked: scaleInt(base.wellStocked, config.mult),
    overstocked: scaleInt(base.overstocked, config.mult),
    replenishmentRisk: scaleInt(base.replenishmentRisk, config.mult),
    expiredDeadStock: scaleInt(base.expiredDeadStock, config.mult),
    nonMoving: scaleInt(base.nonMoving, config.mult),
    topMoving: scaleInt(base.topMoving, config.mult),
  };
}


function getInventoryAgeing(client: ClientKey, range: InventoryWidgetRange) {
  const config = CLIENT_CONFIG[client];
  const widgets = INVENTORY_WIDGETS_BASE[range];

  const zeroToFortyFive = widgets.lowStock + Math.round(widgets.wellStocked * 0.7);
  const fortyFiveToNinety = Math.round(widgets.wellStocked * 0.3) + Math.round(widgets.overstocked * 0.4);
  const ninetyPlus =
    widgets.outOfStock +
    widgets.overstocked +
    widgets.wellStocked +
    widgets.lowStock -
    zeroToFortyFive -
    fortyFiveToNinety;

  return [
    { name: "0–45 day", value: scaleInt(zeroToFortyFive, config.mult) },
    { name: "45–90 day", value: scaleInt(fortyFiveToNinety, config.mult) },
    { name: "90 day+", value: scaleInt(ninetyPlus, config.mult) },
  ];
}

function getActiveSkuCount(client: ClientKey, range: InventoryWidgetRange) {
  const widgets = getInventoryWidgets(client, range);
  return widgets.outOfStock + widgets.lowStock + widgets.wellStocked + widgets.overstocked;
}

function getAllSkuCount(client: ClientKey, range: InventoryWidgetRange) {
  const active = getActiveSkuCount(client, range);
  const multiplierByClient: Record<ClientKey, number> = {
    startup: 2.85,
    test: 2.55,
    api: 3.1,
  };
  return Math.round(active * multiplierByClient[client]);
}

function getInactiveSkuCount(client: ClientKey, range: InventoryWidgetRange) {
  return Math.max(getAllSkuCount(client, range) - getActiveSkuCount(client, range), 0);
}

function getInventoryBucketBars(client: ClientKey, range: InventoryWidgetRange) {
  const widgets = getInventoryWidgets(client, range);
  return [
    ["Out of stock", widgets.outOfStock, "bg-slate-300"],
    ["Low stock", widgets.lowStock, "bg-slate-300"],
    ["Well stocked", widgets.wellStocked, "bg-slate-300"],
    ["Excess stock", widgets.overstocked, "bg-orange-200"],
    ["Non moving", widgets.nonMoving, "bg-slate-300"],
  ] as [string, number, string][];
}

function getLeaderboardRangeLabel(range: InventoryWidgetRange) {
  switch (range) {
    case "yesterday":
      return "previous day";
    case "7d":
      return "previous 7 days";
    case "14d":
      return "previous 14 days";
    case "30d":
      return "previous 30 days";
    case "60d":
      return "previous 60 days";
    case "90d":
      return "previous 90 days";
    case "180d":
      return "previous 180 days";
    default:
      return "previous period";
  }
}

function getDeliveryData(client: ClientKey, view: DeliveryView) {
  const base = DELIVERY_BASE[view];
  const config = CLIENT_CONFIG[client];

  const summary = {
    despatched: scaleInt(base.summary.despatched, config.mult),
    shippedAccepted: scaleInt(base.summary.shippedAccepted, config.mult),
    inTransit: scaleInt(base.summary.inTransit, config.mult),
    outForDelivery: scaleInt(base.summary.outForDelivery, config.mult),
    delivered: scaleInt(base.summary.delivered, config.mult),
    undeliveredReturnedToSender: scaleInt(base.summary.undeliveredReturnedToSender, config.mult),
    returnsCount: scaleInt(base.summary.returnsCount, config.mult),
  };

  const returnsRate = `${((summary.returnsCount / Math.max(summary.despatched, 1)) * 100).toFixed(1)}%`;

  return {
    summary: { ...summary, returnsRate },
    slaTrend: base.slaTrend.map((row) => ({ ...row, sla: adjustPct(row.sla, config.pctDelta) })),
    slaBoard: {
      services: base.services.map((service) => ({
        ...service,
        actual: adjustPct(service.actual, config.pctDelta),
      })),
    },
    overviewBars: [
      ["Despatched", summary.despatched, "bg-slate-300"],
      ["Shipped (Accepted)", summary.shippedAccepted, "bg-slate-300"],
      ["In transit", summary.inTransit, "bg-slate-300"],
      ["Out for delivery", summary.outForDelivery, "bg-slate-300"],
      ["Delivered", summary.delivered, "bg-slate-300"],
      ["Undelivered (returned to Sender)", summary.undeliveredReturnedToSender, "bg-slate-300"],
    ] as [string, number, string][],
    exceptions: base.exceptions.map((row) => ({
      ...row,
      parcel: `${CLIENT_CONFIG[client].parcelPrefix}-${row.parcel}`,
    })),
  };
}



