function ServiceSlaBoard({ services }: { services: SlaServiceRow[] }) {
  const withinTargetCount = services.filter((service) => service.actual >= service.target).length;

  return (
    <Panel
      title="Service type SLA board"
      right={<Badge className="border-slate-200 bg-slate-50 text-slate-700">{withinTargetCount}/{services.length} within SLA</Badge>}
      className="xl:col-span-4"
    >
      <div className="space-y-4">
        {services.map((service) => {
          const delta = Number((service.actual - service.target).toFixed(1));
          const isGood = delta >= 0;
          const badgeText = `${delta > 0 ? "+" : ""}${delta.toFixed(1)} pts`;

          return (
            <div key={service.name} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="font-medium text-slate-900">{service.name}</div>
                  <div className="mt-1 text-sm text-slate-500">Actual vs agreed SLA</div>
                </div>
                <Badge className={isGood ? "border-emerald-200 bg-emerald-50 text-emerald-700" : "border-amber-200 bg-amber-50 text-amber-700"}>
                  {badgeText}
                </Badge>
              </div>

              <div className="mt-4 flex items-end justify-between gap-4">
                <div>
                  <div className="text-3xl font-semibold text-slate-900">{service.actual}%</div>
                  <div className="text-xs uppercase tracking-[0.18em] text-slate-400">Actual</div>
                </div>
                <div className="text-right">
                  <div className="text-lg font-medium text-slate-700">{service.target}%</div>
                  <div className="text-xs uppercase tracking-[0.18em] text-slate-400">Agreed SLA</div>
                </div>
              </div>

              <div className="relative mt-4 h-2 rounded-full bg-slate-100">
                <div
                  className={cn("h-2 rounded-full", isGood ? "bg-emerald-400" : "bg-amber-300")}
                  style={{ width: `${Math.min(service.actual, 100)}%` }}
                />
                <div
                  className="absolute top-1/2 h-4 w-0.5 -translate-y-1/2 bg-slate-500"
                  style={{ left: `calc(${Math.min(service.target, 100)}% - 1px)` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </Panel>
  );
}

function DataHubPage({
  client,
  accessLevel,
  highlightedReportKey,
}: {
  client: ClientKey;
  accessLevel: AccessLevel;
  highlightedReportKey: string | null;
}) {

  const visibleReports = useMemo(
    () => ALL_REPORTS.filter((r) => r.access.includes(accessLevel)),
    [accessLevel]
  );

  return (
    <div className="space-y-6">
      <Panel
        title="Export raw data"
        right={highlightedReportKey ? <Badge className="border-sky-200 bg-sky-50 text-sky-700">Highlighted by widget selection</Badge> : undefined}
      >
        <div className="grid grid-cols-1 items-stretch gap-3 md:grid-cols-2 xl:grid-cols-4">
          <SelectControl value={client} onChange={() => {}} options={CLIENT_OPTIONS} />
          <SelectControl
            value="30d"
            onChange={() => {}}
            options={[
              { value: "yesterday", label: "Yesterday" },
              { value: "7d", label: "Last 7 Days" },
              { value: "14d", label: "Last 14 Days" },
              { value: "30d", label: "Last 30 Days" },
              { value: "60d", label: "Last 60 Days" },
              { value: "90d", label: "Last 90 Days" },
              { value: "180d", label: "Last 180 Days" },
            ]}
          />
        </div>

        <div className="mt-5 grid gap-3">
          {visibleReports.map((row) => {
            const isHighlighted = row.key === highlightedReportKey;
            return (
              <div
                key={row.key}
                className={cn(
                  "rounded-2xl border p-4 transition-colors",
                  isHighlighted ? "border-sky-300 bg-sky-50" : "border-slate-200 bg-slate-50"
                )}
              >
                <div className="grid gap-4 md:grid-cols-[minmax(0,1fr)_auto] md:items-center">
                  <div className="min-w-0">
                    <div className="flex items-center gap-3">
                      <div className="text-base font-medium text-slate-900">{row.name}</div>
                      {isHighlighted ? <Badge className="border-sky-200 bg-sky-100 text-sky-700">Suggested report</Badge> : null}
                    </div>
                    <div className="mt-1 text-sm text-slate-500">{row.desc}</div>
                  </div>

                  <div className="flex flex-col gap-3 md:items-end">
                    <div className="flex items-center gap-3">
                      <Badge className="border-slate-200 bg-white text-slate-700">{row.format}</Badge>
                      <span className="text-sm text-slate-400">Last updated {row.updated}</span>
                    </div>
                    <Button className="w-full md:w-auto">
                      <Download className="mr-2 h-4 w-4" />
                      Download
                    </Button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </Panel>

    </div>
  );
}

export default function App() {
  const [page, setPage] = useState<PageKey>("control");
  const [client, setClient] = useState<ClientKey>("startup");
  const [controlCenterRange, setControlCenterRange] = useState<ControlRange>("30");
  const [inventoryWidgetRange, setInventoryWidgetRange] = useState<InventoryWidgetRange>("30d");
  const [deliveryView, setDeliveryView] = useState<DeliveryView>("last24h");
  const [accessLevel, setAccessLevel] = useState<AccessLevel>("manager");
  const [highlightedReportKey, setHighlightedReportKey] = useState<string | null>(null);
  const [downloadModalOpen, setDownloadModalOpen] = useState(false);
  const [downloadModalLabel, setDownloadModalLabel] = useState("Report");

  useEffect(() => {
    const allowedTabs = ACCESS_TABS[accessLevel];
    if (!allowedTabs.includes(page)) {
      setPage(allowedTabs[0]);
    }
  }, [accessLevel, page]);

  useEffect(() => {
    if (highlightedReportKey) {
      const stillVisible = ALL_REPORTS.some((report) => report.key === highlightedReportKey && report.access.includes(accessLevel));
      if (!stillVisible) setHighlightedReportKey(null);
    }
  }, [accessLevel, highlightedReportKey]);

  const jumpToReport = (reportKey: string) => {
    setHighlightedReportKey(reportKey);
    setPage("data");
  };

  const reportNameByKey = (reportKey: string) => {
    const customNames: Record<string, string> = {
      inbound_putaway: "putaway",
      asn_compliance_rate: "ASN compliance rate",
      asns_expected_pipeline: "ASNs expected and units in pipeline",
      receive_accuracy: "Receive accuracy",
      undelivered_returned_to_sender: "Undelivered returned to sender",
      asn_discrepancy_count: "ASN discrepancy count",
    };
    return customNames[reportKey] ?? ALL_REPORTS.find((report) => report.key === reportKey)?.name ?? "Widget report";
  };

  const openDownloadModal = (reportKey: string) => {
    setDownloadModalLabel(reportNameByKey(reportKey));
    setDownloadModalOpen(true);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      <img src={topBarImage} alt="Existing WMS top bar" className="w-full object-cover object-top border-b border-slate-200" />

      <div className="mx-auto max-w-[1280px] p-5 md:p-7">
        <div className="mb-8 flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h1 className="text-3xl font-semibold tracking-tight md:text-4xl">Fulfilment WMS Dashboard</h1>
            <p className="mt-2 text-sm text-slate-500">{CLIENT_CONFIG[client].label}</p>
          </div>
        </div>

        <div className="mb-6 flex flex-col gap-4 border border-slate-200 bg-white p-4 shadow-sm md:flex-row md:items-center md:justify-between">
          <SegmentedTabs value={page} onChange={setPage} accessLevel={accessLevel} />

          <div className="flex flex-wrap items-start gap-3">
            {page === "control" ? (
              <div className="flex flex-col gap-2">
                <SelectControl value={controlCenterRange} onChange={(value) => setControlCenterRange(value as ControlRange)} options={controlCenterRangeOptions} />
                <SelectControl value={client} onChange={(value) => setClient(value as ClientKey)} options={CLIENT_OPTIONS} />
                <SelectControl value={accessLevel} onChange={(value) => setAccessLevel(value as AccessLevel)} options={ACCESS_OPTIONS} />
              </div>
            ) : (
              <>
                {page === "operations" ? (
                  <SelectControl value={deliveryView} onChange={(value) => setDeliveryView(value as DeliveryView)} options={deliveryViewOptions} />
                ) : null}
                {page !== "data" ? (
                  <SelectControl value={client} onChange={(value) => setClient(value as ClientKey)} options={CLIENT_OPTIONS} />
                ) : null}
                <SelectControl value={accessLevel} onChange={(value) => setAccessLevel(value as AccessLevel)} options={ACCESS_OPTIONS} />
              </>
            )}
          </div>
        </div>

        {page === "control" && accessLevel === "manager" ? (
          <ControlCenterPage client={client} selectedRange={controlCenterRange} onOpenDownloadModal={openDownloadModal} jumpToReport={jumpToReport} />
        ) : null}

        {page === "operations" && (accessLevel === "manager" || accessLevel === "inboundDelivery") ? (
          <OperationsPage client={client} deliveryView={deliveryView} onOpenDownloadModal={openDownloadModal} />
        ) : null}

        {page === "status" && (accessLevel === "manager" || accessLevel === "inventory") ? (
          <InventoryHealthPage client={client} widgetRange={inventoryWidgetRange} onWidgetRangeChange={setInventoryWidgetRange} onOpenDownloadModal={openDownloadModal} />
        ) : null}

        {page === "data" ? <DataHubPage client={client} accessLevel={accessLevel} highlightedReportKey={highlightedReportKey} /> : null}
      </div>


        {downloadModalOpen ? (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
            <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl">
              <div className="flex items-start justify-between gap-4">
                <div>
                  <div className="text-lg font-semibold text-slate-900">Report Downloading...</div>
                  <div className="mt-1 text-sm text-slate-500">{downloadModalLabel}.csv</div>
                </div>
                <button
                  type="button"
                  onClick={() => setDownloadModalOpen(false)}
                  className="rounded-xl border border-slate-200 bg-white p-2 text-slate-700 transition-colors hover:border-slate-300 hover:bg-slate-50"
                  aria-label="Close download popup"
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
              <div className="mt-4 rounded-xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-600">
                Your widget report download has started.
              </div>
            </div>
          </div>
        ) : null}
    </div>
  );
}
